mapper.select:
SELECT s.id, s.showdate, s.showtime, s.sale, s.seat, m.name AS movie_name, c.name AS cinema_name, h.hall_name AS hall_name FROM showtimes s LEFT JOIN movie m ON m.id = s.movie_id LEFT JOIN cinema c ON c.id = s.cinema_id LEFT JOIN hall h ON h.id = s.hall_id
AND s.showdate >= #{start}
AND s.showdate <= #{end}
ORDER BY s.showdate, s.showtime, s.id
